import osimport reimport sysimport timeimport randomimport loggingfrom urllib.parse import urljoin, urlparseimport requestsfrom bs4 import BeautifulSoupfrom dotenv import load_dotenvfrom supabase import create_client# ============================================================# CONFIG# ============================================================load_dotenv()BASE_URL = os.getenv(    "ANICHIN_BASE",    "https://anichin.cafe").rstrip("/")SUPABASE_URL = os.getenv("SUPABASE_URL")SUPABASE_KEY = os.getenv("SUPABASE_KEY")REQUEST_TIMEOUT = int(    os.getenv("REQUEST_TIMEOUT", "25"))MIN_DELAY = float(    os.getenv("MIN_DELAY", "2"))MAX_DELAY = float(    os.getenv("MAX_DELAY", "5"))# ============================================================# LOGGING# ============================================================logging.basicConfig(    level=logging.INFO,    format="%(asctime)s | %(levelname)s | %(message)s")log = logging.getLogger("anichin-scraper")# ============================================================# VALIDATION# ============================================================if not SUPABASE_URL:    raise RuntimeError(        "SUPABASE_URL belum diatur."    )if not SUPABASE_KEY:    raise RuntimeError(        "SUPABASE_KEY belum diatur."    )# ============================================================# CLIENT# ============================================================supabase = create_client(    SUPABASE_URL,    SUPABASE_KEY)session = requests.Session()session.headers.update({    "User-Agent": (        "Mozilla/5.0 (Linux; Android 10; K) "        "AppleWebKit/537.36 "        "(KHTML, like Gecko) "        "Chrome/131.0 Mobile Safari/537.36"    ),    "Accept": (        "text/html,application/xhtml+xml,"        "application/xml;q=0.9,*/*;q=0.8"    ),    "Accept-Language": "id-ID,id;q=0.9,en;q=0.8",})# ============================================================# HELPERS# ============================================================def delay():    seconds = random.uniform(        MIN_DELAY,        MAX_DELAY    )    log.info(        "Delay %.2f detik...",        seconds    )    time.sleep(seconds)def clean_text(value):    if not value:        return ""    return re.sub(        r"\s+",        " ",        value    ).strip()def normalize_url(url):    if not url:        return None    return urljoin(        BASE_URL + "/",        url    ).split("#")[0]def get_slug(url):    parsed = urlparse(url)    slug = parsed.path.strip("/")    if not slug:        return None    return slug.split("/")[-1]def extract_episode_number(text):    if not text:        return None    text = text.upper()    patterns = [        r"EPISODE\s*[-:#]?\s*(\d+(?:\.\d+)?)",        r"EP\s*[-:#]?\s*(\d+(?:\.\d+)?)",        r"EPS\s*[-:#]?\s*(\d+(?:\.\d+)?)",    ]    for pattern in patterns:        match = re.search(            pattern,            text        )        if match:            try:                return float(                    match.group(1)                )            except ValueError:                pass    return Nonedef fetch(url):    delay()    log.info(        "GET %s",        url    )    try:        response = session.get(            url,            timeout=REQUEST_TIMEOUT        )        response.raise_for_status()        log.info(            "HTTP %s",            response.status_code        )        return response.text    except requests.RequestException as exc:        log.error(            "Request gagal: %s",            exc        )        return None# ============================================================# SOUP# ============================================================def soup_from_url(url):    html = fetch(url)    if not html:        return None    return BeautifulSoup(        html,        "html.parser"    )# ============================================================# LINK EXTRACTION# ============================================================def is_anichin_url(url):    if not url:        return False    parsed = urlparse(url)    return (        parsed.netloc.endswith(            "anichin.cafe"        )    )def get_links(soup):    results = []    if not soup:        return results    for a in soup.find_all("a", href=True):        href = normalize_url(            a.get("href")        )        if not href:            continue        if not is_anichin_url(            href        ):            continue        title = clean_text(            a.get_text(" ", strip=True)        )        results.append({            "title": title,            "url": href        })    return results# ============================================================# SERIES DISCOVERY# ============================================================def discover_series():    log.info(        "Memulai discovery serial..."    )    urls = set()    page = 1    while True:        if page == 1:            url = (                f"{BASE_URL}/seri/"            )        else:            url = (                f"{BASE_URL}/seri/page/{page}/"            )        log.info(            "Series page %s",            page        )        soup = soup_from_url(url)        if not soup:            break        links = get_links(            soup        )        new_count = 0        for item in links:            href = item["url"]            title = item["title"]            if not title:                continue            path = urlparse(                href            ).path.lower()            # Jangan ambil halaman umum.            excluded = [                "/seri/",                "/genre/",                "/genres/",                "/ongoing/",                "/completed/",                "/schedule/",                "/category/",            ]            if any(                path.rstrip("/") == x.rstrip("/")                for x in excluded            ):                continue            # Kandidat serial.            if (                "/seri/" in path                or "/series/" in path            ):                if href not in urls:                    urls.add(href)                    new_count += 1        log.info(            "Dapat %s serial baru",            new_count        )        # Kalau halaman tidak menemukan data baru,        # kemungkinan pagination sudah selesai.        if new_count == 0:            break        page += 1        # Pengaman.        if page > 100:            break    return sorted(urls)# ============================================================# FALLBACK SERIES DISCOVERY# ============================================================def discover_series_from_cards():    url = (        f"{BASE_URL}/seri/list-mode/"    )    soup = soup_from_url(        url    )    if not soup:        return []    results = set()    for a in soup.find_all(        "a",        href=True    ):        href = normalize_url(            a["href"]        )        if not href:            continue        if not is_anichin_url(            href        ):            continue        text = clean_text(            a.get_text(                " ",                strip=True            )        )        if not text:            continue        path = urlparse(            href        ).path.lower()        # Hindari link episode.        if "episode" in text.lower():            continue        if (            "/category/" in path            or "/seri/" in path        ):            results.add(href)    return sorted(results)# ============================================================# SERIES DETAIL PARSER# ============================================================def parse_series(url):    log.info(        "Parsing serial: %s",        url    )    soup = soup_from_url(        url    )    if not soup:        return None    title = ""    # H1    h1 = soup.find("h1")    if h1:        title = clean_text(            h1.get_text(                " ",                strip=True            )        )    # Fallback title    if not title:        meta_title = soup.find(            "meta",            property="og:title"        )        if meta_title:            title = clean_text(                meta_title.get(                    "content",                    ""                )            )    # Cover    cover_url = None    og_image = soup.find(        "meta",        property="og:image"    )    if og_image:        cover_url = normalize_url(            og_image.get("content")        )    # Synopsis    synopsis = ""    description = soup.find(        "meta",        attrs={            "name": "description"        }    )    if description:        synopsis = clean_text(            description.get(                "content",                ""            )        )    # Status    status = ""    text = clean_text(        soup.get_text(            " ",            strip=True        )    )    if re.search(        r"\bongoing\b",        text,        re.I    ):        status = "Ongoing"    elif re.search(        r"\bcompleted\b",        text,        re.I    ):        status = "Completed"    # Genres    genres = []    genre_pattern = re.compile(        r"/genres/([^/]+)/?"    )    for a in soup.find_all(        "a",        href=True    ):        match = genre_pattern.search(            a["href"]        )        if match:            genre = clean_text(                a.get_text(                    " ",                    strip=True                )            )            if genre:                genres.append(                    genre                )    genres = list(        dict.fromkeys(            genres        )    )    # Episodes    episodes = parse_episode_links(        soup    )    last_episode = None    if episodes:        numbers = [            e["episode_number"]            for e in episodes            if e["episode_number"]            is not None        ]        if numbers:            last_episode = str(                max(numbers)            ).rstrip("0").rstrip(".")    slug = get_slug(        url    )    return {        "slug": slug,        "title": title or slug or "Unknown",        "cover_url": cover_url,        "synopsis": synopsis,        "status": status,        "genres": genres,        "source_url": url,        "last_episode": last_episode,        "episodes": episodes,    }# ============================================================# EPISODE PARSER# ============================================================def parse_episode_links(    soup):    episodes = []    if not soup:        return episodes    seen = set()    for a in soup.find_all(        "a",        href=True    ):        href = normalize_url(            a.get("href")        )        if not href:            continue        if href in seen:            continue        text = clean_text(            a.get_text(                " ",                strip=True            )        )        if not text:            continue        combined = text        episode_number = (            extract_episode_number(                combined            )        )        if episode_number is None:            # Cek URL            episode_number = (                extract_episode_number(                    href                )            )        if episode_number is None:            continue        seen.add(href)        episodes.append({            "episode_number":                episode_number,            "title": text,            "episode_url": href,        })    episodes.sort(        key=lambda x: (            x["episode_number"]            if x["episode_number"]            is not None            else 999999        )    )    return episodes# ============================================================# EPISODE DETAIL# ============================================================def enrich_episode(    episode):    url = episode[        "episode_url"    ]    soup = soup_from_url(        url    )    if not soup:        return episode    title = episode[        "title"    ]    h1 = soup.find(        "h1"    )    if h1:        parsed_title = clean_text(            h1.get_text(                " ",                strip=True            )        )        if parsed_title:            title = parsed_title    episode[        "title"    ] = title    return episode# ============================================================# SUPABASE SERIES# ============================================================def get_existing_series(    slug):    try:        response = (            supabase            .table("series")            .select("id,slug")            .eq("slug", slug)            .limit(1)            .execute()        )        if response.data:            return response.data[0]    except Exception as exc:        log.error(            "Gagal membaca series %s: %s",            slug,            exc        )    return Nonedef upsert_series(    data):    payload = {        "slug": data["slug"],        "title": data["title"],        "cover_url": data["cover_url"],        "synopsis": data["synopsis"],        "status": data["status"],        "source_url": data["source_url"],        "genres": data["genres"],        "last_episode": data["last_episode"],        "updated_at": "now()",        "last_scraped_at": "now()",    }    try:        response = (            supabase            .table("series")            .upsert(                payload,                on_conflict="slug"            )            .execute()        )        if response.data:            return response.data[0]        # fallback        existing = get_existing_series(            data["slug"]        )        return existing    except Exception as exc:        log.error(            "Gagal upsert series %s: %s",            data["title"],            exc        )        return None# ============================================================# SUPABASE EPISODE# ============================================================def upsert_episode(    series_id,    episode):    payload = {        "series_id": series_id,        "episode_number":            episode["episode_number"],        "title":            episode["title"],        "episode_url":            episode["episode_url"],        "updated_at":            "now()",    }    try:        response = (            supabase            .table("episodes")            .upsert(                payload,                on_conflict="episode_url"            )            .execute()        )        return bool(            response.data        )    except Exception as exc:        log.error(            "Episode gagal: %s | %s",            episode["episode_url"],            exc        )        return False# ============================================================# PROCESS SERIES# ============================================================def process_series(    url):    data = parse_series(        url    )    if not data:        return {            "series": False,            "episodes": 0        }    log.info(        "SERIAL: %s",        data["title"]    )    row = upsert_series(        data    )    if not row:        log.error(            "Tidak bisa mendapatkan ID series."        )        return {            "series": False,            "episodes": 0        }    series_id = row["id"]    episode_count = 0    for episode in data[        "episodes"    ]:        # Ambil detail episode hanya jika        # memang diperlukan.        episode = enrich_episode(            episode        )        if upsert_episode(            series_id,            episode        ):            episode_count += 1    return {        "series": True,        "episodes": episode_count    }# ============================================================# MAIN# ============================================================def main():    started = time.time()    print()    print("=" * 60)    print("        NUSADHUA ANICHIN SCRAPER")    print("=" * 60)    print()    log.info(        "Source: %s",        BASE_URL    )    # --------------------------------------------------------    # DISCOVER    # --------------------------------------------------------    series_urls = discover_series()    if not series_urls:        log.warning(            "Discovery utama kosong."        )        series_urls = (            discover_series_from_cards()        )    series_urls = list(        dict.fromkeys(            series_urls        )    )    log.info(        "Total kandidat serial: %s",        len(series_urls)    )    # --------------------------------------------------------    # PROCESS    # --------------------------------------------------------    total_series = 0    total_episodes = 0    for index, url in enumerate(        series_urls,        start=1    ):        print()        print(            f"[{index}/{len(series_urls)}] "            f"{url}"        )        try:            result = process_series(                url            )            if result["series"]:                total_series += 1            total_episodes += (                result["episodes"]            )        except Exception as exc:            log.exception(                "Series gagal: %s",                exc            )            continue    elapsed = (        time.time() - started    )    print()    print("=" * 60)    print("SCRAPER SELESAI")    print("=" * 60)    print(        f"Series diproses : {total_series}"    )    print(        f"Episode diproses: {total_episodes}"    )    print(        f"Waktu           : {elapsed:.2f} detik"    )    print("=" * 60)if __name__ == "__main__":    try:        main()    except KeyboardInterrupt:        print(            "\nScraper dihentikan."        )        sys.exit(0)    except Exception as exc:        log.exception(            "Fatal error: %s",            exc        )        sys.exit(1)